package br.com.loja.checkout;

import java.math.BigDecimal;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.Function;
import java.util.stream.Collectors;

import org.springframework.stereotype.Service;

import br.com.loja.catalog.Product;
import br.com.loja.catalog.ProductRepository;
import br.com.loja.club.ClubTier;
import br.com.loja.common.ApiException;
import br.com.loja.common.ErrorCode;
import br.com.loja.common.Money;
import br.com.loja.coupon.Coupon;
import br.com.loja.coupon.CouponContext;
import br.com.loja.order.OrderRepository;
import br.com.loja.payment.PaymentOption;
import br.com.loja.payment.PaymentOption.PaymentCharge;
import br.com.loja.payment.PaymentOption.PaymentContext;
import br.com.loja.shipping.Region;
import br.com.loja.shipping.ShippingOption;
import br.com.loja.shipping.ShippingQuote;
import br.com.loja.shipping.ShippingRequest;

/** Calcula o resumo da compra. É a única fonte dos valores, tanto do resumo quanto do pedido registrado. */
@Service
public class CheckoutService {

    private static final String COUPON_CAP_RATE = "0.30";

    private final ProductRepository products;
    private final OrderRepository orders;
    private final Map<String, ShippingOption> shippingOptions;
    private final Map<String, Coupon> coupons;
    private final Map<String, ClubTier> tiers;
    private final Map<String, PaymentOption> paymentOptions;

    CheckoutService(ProductRepository products, OrderRepository orders, List<ShippingOption> shippingOptions,
                    List<Coupon> coupons, List<ClubTier> tiers, List<PaymentOption> paymentOptions) {
        this.products = products;
        this.orders = orders;
        this.shippingOptions = index(shippingOptions, ShippingOption::code);
        this.coupons = index(coupons, Coupon::code);
        this.tiers = index(tiers, ClubTier::code);
        this.paymentOptions = index(paymentOptions, PaymentOption::code);
    }

    public OrderSummary summarize(CheckoutRequest request) {
        validateStructure(request);
        List<CartLine> lines = loadLines(request.items());

        ClubTier tier = find(tiers, request.clubTier(), ErrorCode.INVALID_CLUB_TIER);
        Region region = Region.parse(request.region()).orElseThrow(() -> new ApiException(ErrorCode.INVALID_REGION));
        String zip = request.zipCode();
        if (zip == null || !zip.matches("\\d{8}")) {
            throw new ApiException(ErrorCode.INVALID_ZIP_CODE);
        }
        ShippingOption shipping = find(shippingOptions, request.shippingMethod(), ErrorCode.INVALID_SHIPPING_METHOD);

        BigDecimal subtotal = lines.stream().map(CartLine::total).reduce(Money.ZERO, BigDecimal::add);
        BigDecimal weight = lines.stream()
                .map(l -> l.product().weightKg().multiply(BigDecimal.valueOf(l.quantity())))
                .reduce(BigDecimal.ZERO, BigDecimal::add);
        ShippingQuote quote = shipping.quote(new ShippingRequest(zip, region, weight));
        BigDecimal shippingCost = tier.waivesFreight() && shipping.freightWaivableByClub() ? Money.ZERO
                : quote.cost();

        BigDecimal couponDiscount = Money.ZERO;
        if (request.coupon() != null) {
            Coupon coupon = find(coupons, request.coupon(), ErrorCode.INVALID_COUPON);
            boolean firstPurchase = !orders.hasPurchaseByCustomer(request.customer().cpf());
            BigDecimal raw = coupon.discount(new CouponContext(lines, subtotal, shipping, shippingCost, firstPurchase));
            couponDiscount = Money.round(raw).min(Money.percent(subtotal, COUPON_CAP_RATE));
        }

        PaymentOption payment = find(paymentOptions, request.paymentMethod(), ErrorCode.INVALID_PAYMENT_METHOD);
        int installments = request.installments() == null ? 1 : request.installments();
        payment.validateInstallments(installments);

        BigDecimal insurance = region.insuranceFor(subtotal);
        BigDecimal orderTotal = subtotal.subtract(couponDiscount).add(shippingCost).add(insurance);
        payment.validateAvailability(orderTotal);
        PaymentCharge charge = payment.charge(new PaymentContext(orderTotal, installments, request.coupon() != null));

        return new OrderSummary(subtotal, couponDiscount, shippingCost, quote.days(), insurance,
                charge.finalTotal().subtract(orderTotal), charge.finalTotal(), installments,
                charge.installmentAmount(), tier.credit(subtotal), tier.gift(subtotal));
    }

    private void validateStructure(CheckoutRequest request) {
        if (request == null || request.items() == null || request.items().isEmpty()
                || request.customer() == null || isBlank(request.customer().cpf())
                || isBlank(request.customer().email())) {
            throw new ApiException(ErrorCode.INVALID_ORDER);
        }
        Set<String> seen = new HashSet<>();
        for (CheckoutRequest.Item item : request.items()) {
            if (item == null || isBlank(item.sku()) || item.quantity() == null || item.quantity() <= 0
                    || !seen.add(item.sku())) {
                throw new ApiException(ErrorCode.INVALID_ORDER);
            }
        }
    }

    private List<CartLine> loadLines(List<CheckoutRequest.Item> items) {
        Map<String, Product> found = products.findAllBySkus(items.stream().map(CheckoutRequest.Item::sku).toList())
                .stream().collect(Collectors.toMap(Product::sku, Function.identity()));
        if (items.stream().anyMatch(i -> !found.containsKey(i.sku()))) {
            throw new ApiException(ErrorCode.UNKNOWN_PRODUCT);
        }
        if (found.values().stream().anyMatch(Product::discontinued)) {
            throw new ApiException(ErrorCode.PRODUCT_DISCONTINUED);
        }
        if (items.stream().anyMatch(i -> found.get(i.sku()).stock() < i.quantity())) {
            throw new ApiException(ErrorCode.INSUFFICIENT_STOCK);
        }
        return items.stream().map(i -> new CartLine(found.get(i.sku()), i.quantity())).toList();
    }

    private static boolean isBlank(String s) {
        return s == null || s.isBlank();
    }

    private static <T> T find(Map<String, T> registry, String code, ErrorCode error) {
        T found = code == null ? null : registry.get(code);
        if (found == null) {
            throw new ApiException(error);
        }
        return found;
    }

    private static <T> Map<String, T> index(List<T> beans, Function<T, String> code) {
        Map<String, T> map = new LinkedHashMap<>();
        beans.forEach(b -> map.put(code.apply(b), b));
        return map;
    }
}
package br.com.loja.order;

import java.time.Clock;
import java.time.Duration;
import java.time.Instant;
import java.time.temporal.ChronoUnit;
import java.util.List;
import java.util.UUID;

import org.springframework.dao.DuplicateKeyException;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;

import br.com.loja.catalog.ProductRepository;
import br.com.loja.checkout.CheckoutRequest;
import br.com.loja.checkout.CheckoutService;
import br.com.loja.checkout.OrderSummary;
import br.com.loja.common.ApiException;
import br.com.loja.common.ErrorCode;
import br.com.loja.customer.CustomerRepository;

@Service
public class OrderService {

    private static final String OK = "OK";
    private static final Duration PAYMENT_WINDOW = Duration.ofHours(48);

    private final CheckoutService checkout;
    private final OrderRepository orders;
    private final ProductRepository products;
    private final CustomerRepository customers;
    private final List<OrderEventListener> listeners;
    private final Clock clock;
    private final TransactionTemplate tx;

    OrderService(CheckoutService checkout, OrderRepository orders, ProductRepository products,
                 CustomerRepository customers, List<OrderEventListener> listeners, Clock clock,
                 PlatformTransactionManager transactionManager) {
        this.checkout = checkout;
        this.orders = orders;
        this.products = products;
        this.customers = customers;
        this.listeners = listeners;
        this.clock = clock;
        this.tx = new TransactionTemplate(transactionManager);
    }

    public Order create(CheckoutRequest request) {
        OrderSummary summary = checkout.summarize(request);
        List<OrderItem> items = request.items().stream()
                .map(i -> new OrderItem(i.sku(), i.quantity())).toList();
        Order order = new Order(UUID.randomUUID().toString(), request.customer().cpf(),
                OrderStatus.AWAITING_PAYMENT, Instant.now(clock).truncatedTo(ChronoUnit.SECONDS), summary, items,
                null, null, null);
        try {
            tx.executeWithoutResult(s -> customers.createIfAbsent(request.customer().cpf(), request.customer().email()));
        } catch (DuplicateKeyException e) {
            // outra máquina criou o mesmo cliente agora há pouco: está tudo certo
        }
        tx.executeWithoutResult(s -> orders.insert(order));
        return order;
    }

    public Order get(String id) {
        return orders.findById(id).orElseThrow(() -> new ApiException(ErrorCode.ORDER_NOT_FOUND));
    }

    private record PaymentResult(Order order, ErrorCode error) {
    }

    public Order confirmPayment(String id, String transactionId, String paidAtText) {
        PaymentResult result = tx.execute(s -> processPayment(id, transactionId, paidAtText));
        if (result.error() != null) {
            throw new ApiException(result.error(), HttpStatus.CONFLICT);
        }
        return result.order();
    }

    private PaymentResult processPayment(String id, String transactionId, String paidAtText) {
        Order order = lock(id);
        Instant paidAt = parseInstant(paidAtText);
        if (transactionId == null || transactionId.isBlank() || paidAt == null) {
            throw new ApiException(ErrorCode.INVALID_ORDER);
        }
        if (transactionId.equals(order.paymentTransactionId())) {
            return outcomeOf(order, order.paymentOutcome());
        }
        requireMove(order, OrderStatus.PAID);

        if (paidAt.isAfter(order.createdAt().plus(PAYMENT_WINDOW))) {
            return failPayment(order, transactionId, ErrorCode.ORDER_EXPIRED);
        }
        if (!products.reserve(order.items())) {
            return failPayment(order, transactionId, ErrorCode.INSUFFICIENT_STOCK);
        }
        orders.recordPayment(id, transactionId, OK, OrderStatus.PAID);
        Order paid = get(id);
        listeners.forEach(l -> l.onPaid(paid));
        return new PaymentResult(paid, null);
    }

    private PaymentResult failPayment(Order order, String transactionId, ErrorCode error) {
        orders.recordPayment(order.id(), transactionId, error.name(), OrderStatus.CANCELLED);
        Order cancelled = get(order.id());
        listeners.forEach(l -> l.onCancelled(cancelled, false));
        return new PaymentResult(cancelled, error);
    }

    private static PaymentResult outcomeOf(Order order, String outcome) {
        return new PaymentResult(order, OK.equals(outcome) ? null : ErrorCode.valueOf(outcome));
    }

    public Order ship(String id, String trackingCode) {
        return tx.execute(s -> {
            Order order = lock(id);
            if (trackingCode == null || trackingCode.isBlank()) {
                throw new ApiException(ErrorCode.INVALID_ORDER);
            }
            requireMove(order, OrderStatus.SHIPPED);
            orders.recordShipment(id, trackingCode);
            Order shipped = get(id);
            listeners.forEach(l -> l.onShipped(shipped));
            return shipped;
        });
    }

    public Order deliver(String id) {
        return tx.execute(s -> {
            Order order = lock(id);
            requireMove(order, OrderStatus.DELIVERED);
            orders.updateStatus(id, OrderStatus.DELIVERED);
            return get(id);
        });
    }

    public Order cancel(String id) {
        return tx.execute(s -> {
            Order order = lock(id);
            requireMove(order, OrderStatus.CANCELLED);
            boolean wasPaid = order.status() == OrderStatus.PAID;
            if (wasPaid) {
                products.release(order.items());
            }
            orders.updateStatus(id, OrderStatus.CANCELLED);
            Order cancelled = get(id);
            listeners.forEach(l -> l.onCancelled(cancelled, wasPaid));
            return cancelled;
        });
    }

    private Order lock(String id) {
        return orders.findByIdForUpdate(id).orElseThrow(() -> new ApiException(ErrorCode.ORDER_NOT_FOUND));
    }

    private static void requireMove(Order order, OrderStatus target) {
        if (!order.status().canMoveTo(target)) {
            throw new ApiException(ErrorCode.OPERATION_NOT_ALLOWED);
        }
    }

    private static Instant parseInstant(String text) {
        try {
            return text == null ? null : Instant.parse(text);
        } catch (java.time.format.DateTimeParseException e) {
            return null;
        }
    }
}
package br.com.loja.order;

import java.time.Instant;
import java.util.List;

import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RestController;

import br.com.loja.checkout.CheckoutRequest;
import br.com.loja.checkout.OrderSummary;

@RestController
class OrderController {

    record OrderResponse(String id, OrderStatus status, Instant createdAt, OrderSummary summary,
                         List<OrderItem> items, String trackingCode) {
        static OrderResponse of(Order o) {
            return new OrderResponse(o.id(), o.status(), o.createdAt(), o.summary(), o.items(), o.trackingCode());
        }
    }

    record PaymentRequest(String transactionId, String paidAt) {
    }

    record ShipmentRequest(String trackingCode) {
    }

    private final OrderService orders;

    OrderController(OrderService orders) {
        this.orders = orders;
    }

    @PostMapping("/orders")
    ResponseEntity<OrderResponse> create(@RequestBody(required = false) CheckoutRequest request) {
        return ResponseEntity.status(HttpStatus.CREATED).body(OrderResponse.of(orders.create(request)));
    }

    @GetMapping("/orders/{id}")
    OrderResponse get(@PathVariable String id) {
        return OrderResponse.of(orders.get(id));
    }

    @PostMapping("/orders/{id}/payment")
    OrderResponse pay(@PathVariable String id, @RequestBody(required = false) PaymentRequest body) {
        return OrderResponse.of(orders.confirmPayment(id, body == null ? null : body.transactionId(),
                body == null ? null : body.paidAt()));
    }

    @PostMapping("/orders/{id}/shipment")
    OrderResponse ship(@PathVariable String id, @RequestBody(required = false) ShipmentRequest body) {
        return OrderResponse.of(orders.ship(id, body == null ? null : body.trackingCode()));
    }

    @PostMapping("/orders/{id}/delivery")
    OrderResponse deliver(@PathVariable String id) {
        return OrderResponse.of(orders.deliver(id));
    }

    @PostMapping("/orders/{id}/cancellation")
    OrderResponse cancel(@PathVariable String id) {
        return OrderResponse.of(orders.cancel(id));
    }
}

